from pathlib import Path
import json
import re

HERE=Path(__file__).resolve().parent
PEOPLE=[]
def add(key,name,tag,slots,note,profile=None,legacy_index=None,title=None,aliases=()):
    PEOPLE.append(dict(key=key,name=name,tag=tag,slots=list(slots),description=note,
        profile=profile,legacy_index=legacy_index,wikipedia_title=title or name,aliases=list(aliases)))
def ger(key,name,slots,note,**kw):add(key,name,'GER',slots,note,**kw)
def ddr(key,name,slots,note,**kw):add(key,name,'DDR',slots,note,**kw)

