def main():
    assert len({(r['tag'],r['key']) for r in PEOPLE})==len(PEOPLE)
    (HERE/'catalogue.json').write_text(json.dumps(dict(project='IMPERIA COLD WAR',people=PEOPLE),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print({tag:sum(r['tag']==tag for r in PEOPLE) for tag in ('GER','DDR')},'unique people',len({r['key'] for r in PEOPLE}))

if __name__=='__main__':main()
